traps.trap01.txt:
// 追到南宫彩虹

	PlayerGoto(14, 22);
	SetPlayerDir(4);
	Say("张如梦：多美的夕阳啊！", 12);
	Sleep(500);
	Say("南宫彩虹：你……又追上来做什么？", 29);
	Say("张如梦：你是在这里歇脚，还是在观看这里的风景？", 19);
	Say("南宫彩虹：都不是。", 29);
	Say("张如梦：莫非……你在等我？", 19);
	Say("南宫彩虹：是的。", 29);
	Say("张如梦：为什么？", 19);
	Say("南宫彩虹：我们总得有一个了结，这个地方最好。", 29):
	Say("张如梦：的确，雄关万里，气势磅礴，若死后能埋在这里，也是一桩美事。", 19);
	Say("南宫彩虹：那图就在我身上。", 29);
	Say("张如梦：我知道，否则我就不会来了。", 19);
	Say("南宫彩虹：你志在必得？", 29);
	Say("张如梦：家父所托，不敢有违。", 19);
	Say("南宫彩虹：我也是家父所托。", 29);
	Say("张如梦：这……", 19);
	Say("南宫彩虹：你动手吧。", 29);
	Say("张如梦：我……", 19);
	Say("南宫彩虹：你要拿到图，你就必须杀了我。就象我要带走图，就必须杀掉你一样。你若不杀我，你就不可能拿到图。", 29);
	Say("张如梦：难道我们就只有兵戎相见这条路？", 19);
	Say("南宫彩虹：还有什么其它的路？我爹爹杀了你的爹爹，你的妹妹和你未来的妹夫又杀了我的爹爹——就算他们不杀，你也迟早要出手的，是么？", 29)
	Say("张如梦：不错。", 19);
	Say("南宫彩虹：其实你早就应该杀我，我也早就应该杀了你，是么？", 29);
	Say("张如梦：不错。", 19);
	Say("南宫彩虹：那我们现在动手，也不算太迟吧？", 29);
	Say("张如梦：早知现在，何必当初？", 19);
	
	Watch("张如梦", "南宫彩虹", 0);
	
	Say("南宫彩虹：当初怎么了？其实你早就知道了我的身份？", 29);
	Say("张如梦：是的。", 19);
	Say("南宫彩虹：那你为什么不告诉你父亲？", 29);
	Say("张如梦：我那时并不了解他。当我了解他的时候，他已经不在人世了。", 19);
	Say("南宫彩虹：我去临安除开寻找“山河社稷图”外，还有其它任务在身。", 29);
	Say("张如梦：监视我父亲？", 19);
	Say("南宫彩虹：如果他有异心，就找机会杀了他！", 29);
	Say("张如梦：可是你虽然知道他的事情却没有动手——你还要监视秦桧吗？", 19);
	Say("南宫彩虹：他不需要监视。", 29);
	Say("张如梦：你……还不想面对我？", 19);
	Say("南宫彩虹：我一直想面对你，见到你了又不敢面对你。不管是我死在你的手上，还是你死在我的手上，其实都没有什么分别的。", 29);
	Say("张如梦：心死比人死更痛苦，这么多年来我的心已经死了很多，每天唯有借酒来残延剩下的一丝气息。", 19);
	Say("南宫彩虹：你大可不必为我这么糟蹋自己。", 19);
	Say("张如梦：我也不单是为你。", 19);
	Say("南宫彩虹：还有你的父亲？", 29);
	Say("张如梦：是的，他死了，我为他死的心却活了。", 19);
	Say("南宫彩虹：所以你才来追赶我，和我拼命？", 29);
	Say("张如梦：正如你所说，我们迟早是要有个了结的。", 19);	
	Say("南宫彩虹：除了一死，还有什么了结？", 29);
	Say("张如梦：难道……难道我们就非要你死我活？", 19);
	Say("南宫彩虹：难道我们还有别的出路？", 29);
	Say("张如梦：我们……我们不可以置身世外么？", 19);
	Say("南宫彩虹：你不想完成你父亲的嘱托了？你真的做得到么？", 29);
	Say("张如梦：只要你愿意和我在一起。", 19);
	Say("南宫彩虹：宋军胜利在望，你当然可以这么说，可是我呢？我怎样去面对我的国家，人民，和亲人？", 32);
	Say("张如梦：如果不是你们金国人挑起这场战争，不把中原占去，不把战火烧到黄河，又哪会有这么多的……", 19);
	Say("南宫彩虹：现在说这些有什么用？现在我们谁也回避不了。这一切……也许就是天意！", 32);
	
	PlayerGoto(14, 20);
	Watch("张如梦", "南宫彩虹", 0);
	Say("张如梦：不，我不要这样的天意，我不要永远活在仇恨里。彩虹，忘记你爹，忘记金国，忘记大宋，我们到塞北、到西域去、到一个没有人找得到我们的地方……天底下一定可以找到一个让我们忘记仇恨，平平静静过日子的地方！", 16);
	Say("南宫彩虹：太晚了，太晚了……", 32);
	Say("张如梦：不会的，这一切终会有个了结……好吧，彩虹，我知道你的心意。既然我们生不能在一起，但愿死后能相依。彩虹，我问你，其实我早就想问你的，但一直没敢问。你现在愿意嫁给我吗？", 19);
	Say("南宫彩虹：……", 30);
	Sleep(1000);
	SetNpcDir("南宫彩虹",4);
	Sleep(1000);

	SetNpcActionFile("南宫彩虹", 0, "mpc054_2.asf");
	SetNpcActionFile("南宫彩虹", 1, "mpc054_2.asf");
	NpcSpecialAction("南宫彩虹", "mpc054_1.asf");    //南宫彩虹跪下来
	Sleep(2000);
	
	Say("张如梦：彩虹……", 16);
	Say("南宫彩虹：如梦，你也跪下来呀！", 30);

	Sleep(500);
	PlayerGoto(13, 21);
	SetPlayerDir(4);
	Sleep(500);

	SetNpcActionFile("张如梦", 0, "mpc055_2.asf");
	SetNpcActionFile("张如梦", 1, "mpc055_2.asf");
	NpcSpecialAction("张如梦", "mpc055_1.asf");      //张如梦跪下来
	Sleep(1000);

	Say("南宫彩虹：苍天作主，青山为媒，我南宫彩虹愿与张郎结为夫妻。", 30);
	Say("张如梦：彩虹——", 12);
	Sleep(500);
	Say("南宫彩虹：一拜苍天，请苍天作证，我南宫彩虹愿嫁张如梦为妻，如彩虹后死，愿扎草结庐，与夫君朝夕相伴，一生相随，不踏中原一步。", 30);
	
	NpcSpecialAction("南宫彩虹", "mpc054_3.asf");    //南宫彩虹下拜
	NpcSpecialAction("张如梦", "mpc055_3.asf");      //张如梦下拜
	Sleep(3000);
	
	Say("张如梦：二拜青山，请青山为媒，我张如梦今日娶彩虹为妻，矢志不渝。若今日一战后如梦尚余残生，当自遁空门，每日与爱妻诵经念佛，至死方休！", 11);
	
	NpcSpecialAction("南宫彩虹", "mpc054_3.asf");    //南宫彩虹下拜
	NpcSpecialAction("张如梦", "mpc055_3.asf");      //张如梦下拜
	Sleep(3000);
	
	Say("三拜神明，请神明作主，如果我们生不能白头偕老永相伴，但愿死后能够相依相伴不分离！", 112);

	NpcSpecialAction("南宫彩虹", "mpc054_3.asf");    //南宫彩虹下拜
	NpcSpecialAction("张如梦", "mpc055_3.asf");      //张如梦下拜
	Sleep(3000);
	
	SetNpcActionFile("南宫彩虹", 0, "npc005_st.asf");
	SetNpcActionFile("南宫彩虹", 1, "npc005_pst.asf");
	NpcSpecialAction("南宫彩虹", "mpc054_4.asf");    //南宫彩虹站起来
	Sleep(1000);
	SetNpcActionFile("张如梦", 0, "npc002_st.asf");
	SetNpcActionFile("张如梦", 1, "npc002_pst.asf");
	NpcSpecialAction("张如梦", "mpc055_4.asf");      //张如梦站起来
	Sleep(1000);
	
	Watch("南宫彩虹", "张如梦", 0);
	Say("南宫彩虹：如梦，你后悔吗？", 30);
	Say("张如梦：哈哈哈哈！我怎么会后悔？看天下英雄，谁有我张如梦福气？苍天作主，青山为媒，能够拥有如此相知相爱的娇妻，人生如此，夫复何求？", 12);
	Say("南宫彩虹：如梦，如果我能够活下来，我定会随你远走关外，找一处清静处所，陪你一生一世。", 30);
	Say("张如梦：若是我活了下来，我就上峨嵋山剃度出家，替你颂经念佛，直到死后魂魄相依，就算是孤魂野鬼，若是有你相伴，也胜却人间无数！", 12);
	Sleep(500);
	Say("南宫彩虹：上天既已成全了我们的这段缘份，那么我们的恩怨终究要有个了结，逃也是逃不掉的……", 33);
	Say("张如梦：哈哈哈哈！今生能娶你为妻，我张如梦已经再无遗憾！况且，这雄关万里，残阳如血，倘若能够死在这里，也是人生一桩美事！上天真是太厚爱我张如梦了！", 12);
	Say("南宫彩虹：如梦，动手吧！", 29);
	SetNpcDeathScript("南宫彩虹", "南宫彩虹死亡.txt");
	SetNpcDeathScript("张如梦", "张如梦死亡.txt");
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("南宫彩虹", 1);
	SetNpcRelation("张如梦", 0);
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	Assign($Event, 695);
	SetMapTrap(1, "");
	//SetMapTrap(2, "trap02.txt");
	
	AddObj("门类障碍.ini",8,41,0);
	AddObj("门类障碍.ini",9,42,0);
	AddObj("门类障碍.ini",9,43,0);
	AddObj("门类障碍.ini",10,44,0);
	AddObj("门类障碍.ini",10,45,0);
		
	SetTimeScript(0, "剑门关之战.txt");
	OpenTimeLimit(60);
	HideTimerWnd();
	Return;
